entity Prob_5_40_vhdl is	port (E, F, clock, reset_b: in bit);end Prob_5_40_vhdl;architecture Behavioral of Prob_5_40_vhdl is	constant s0: bit_vector (1 downto 0) := "00"; 	constant s1: bit_vector (1 downto 0) := "01";	constant s2: bit_vector (1 downto 0) := "10";	constant s3: bit_vector (1 downto 0) := "11";	signal state, next_state: bit_vector (1 downto 0);begin	process (clock, reset_b) begin     	if reset_b = '0' then state <= s0;    	elsif clock'event and clock = '1' then state <= next_state; end if;	end process;		process (state, E, F) begin		next_state <= s0;		case (state) is      	when s0 =>	if E = '0' then next_state <= s0;    			elsif F = '1' then next_state <= s1; else next_state <= s3;    			end if;   			when s1 =>	if E = '0' then next_state <= s1; 				elsif F = '1' then next_state <= s2; else next_state <= s0;				end if;   			when s2 =>	if E = '0' then next_state <= s2; 				elsif F = '1' then next_state <= s3; else next_state <= s1;				end if;   			when s3 =>	if E = '0' then next_state <= s3; 				elsif F = '1' then next_state <= s0; else next_state <= s2;				end if;   			when others =>	next_state <= s0;		end case;	end process;end Behavioral;